<?php if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("INSERT INTO sourcing_requests(request_no,title,department,estimated_value,status,request_date) VALUES(?,?,?,?,?,?)");$s->execute([$_POST['request_no'],$_POST['title'],$_POST['department'],$_POST['estimated_value'],$_POST['status'],$_POST['request_date']]);echo'<div class="alert alert-success">Sourcing request berhasil ditambahkan.</div>';}$rows=$pdo->query("SELECT * FROM sourcing_requests ORDER BY id DESC")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Sourcing Management</h2><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#addSourcing">+ Sourcing Request</button></div><div class="card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Request No</th><th>Title</th><th>Department</th><th>Est. Value</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['request_no']?></td><td><?=$r['title']?></td><td><?=$r['department']?></td><td>Rp <?=number_format($r['estimated_value'],0,',','.')?></td><td><?=$r['status']?></td><td><?=$r['request_date']?></td></tr><?php endforeach;?></tbody></table></div></div><div class="modal fade" id="addSourcing"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-header"><h5>Add Sourcing Request</h5></div><div class="modal-body"><?php foreach(['request_no'=>'Request No','title'=>'Title','department'=>'Department','estimated_value'=>'Estimated Value','request_date'=>'Request Date'] as $n=>$l):?><label class="form-label"><?=$l?></label><input name="<?=$n?>" type="<?=$n==='request_date'?'date':'text'?>" class="form-control mb-2" required><?php endforeach;?><label class="form-label">Status</label><select name="status" class="form-select"><option>Draft</option><option>Review</option><option>RFQ</option><option>Evaluation</option><option>Awarded</option></select></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div></div>